// Der Webhook wird nur vom "Keyword-Research starten" Button aufgerufen.
// Daher reicht es, die Task-Daten einfach durchzureichen.
const task = $input.first().json;
const customFields = task.custom_fields || [];

// Prüfe ob der Task im richtigen Status ist (optional safety check)
const status = task.status?.status?.toLowerCase() || '';

return [{
  json: {
    task_id: task.id,
    task_name: task.name,
    tags: task.tags || [],
    custom_fields: customFields,
    status: status
  }
}];

// Task-Daten aus dem gefilterten Ergebnis extrahieren
const task = $('Filter: Keyword-Research starten').item.json;
const customFields = task.custom_fields || [];

// Themen-Cluster: Dropdown-Wert ist ein orderindex oder UUID
const clusterField = customFields.find(f => f.name && f.name.toLowerCase().includes('themen-cluster'));

// Dropdown value = orderindex (0,1,2,3) wenn gesetzt, sonst null
// Auch die Options-Liste für die Zuordnung weitergeben
const themenClusterValue = clusterField?.value ?? null;
const themenClusterOptions = clusterField?.type_config?.options || [];

// Cluster-Name für Labels (aus Option oder Task Name)
let themenClusterName = task.task_name || '';
if (themenClusterValue !== null && themenClusterOptions.length > 0) {
  const opt = themenClusterOptions.find(o => o.orderindex === themenClusterValue);
  if (opt) themenClusterName = opt.name;
}

// Kunde aus Tags (erster Tag) — Fallback 'covago'
const kunde = (task.tags && task.tags.length > 0) ? task.tags[0].name : 'covago';

return [{
  json: {
    seed_keyword: task.task_name,
    task_id: task.task_id,
    kunde: kunde,
    themen_cluster: themenClusterName,
    themen_cluster_value: themenClusterValue,
    themen_cluster_options: themenClusterOptions
  }
}];

// Alle Keywords aus beiden API-Antworten zusammenführen
const suggestionsRaw = $('DataForSEO: Keyword Suggestions').item.json;
const relatedRaw = $('DataForSEO: Related Keywords').item.json;

const allKeywords = [];

// Suggestions parsen
const sugTasks = suggestionsRaw.tasks || [];
for (const task of sugTasks) {
  const items = task?.result?.[0]?.items || [];
  for (const item of items) {
    const kw = item.keyword_data || item;
    allKeywords.push({
      keyword: (kw.keyword || item.keyword || '').toLowerCase().trim(),
      search_volume: kw.keyword_info?.search_volume || item.keyword_info?.search_volume || 0,
      cpc: kw.keyword_info?.cpc || item.keyword_info?.cpc || 0,
      competition: kw.keyword_info?.competition || item.keyword_info?.competition || 0,
      search_intent: (kw.search_intent_info?.main_intent || item.search_intent_info?.main_intent || 'informational').toLowerCase(),
      source: 'suggestions'
    });
  }
}

// Related parsen
const relTasks = relatedRaw.tasks || [];
for (const task of relTasks) {
  const items = task?.result?.[0]?.items || [];
  for (const item of items) {
    const kd = item.keyword_data || {};
    allKeywords.push({
      keyword: (kd.keyword || '').toLowerCase().trim(),
      search_volume: kd.keyword_info?.search_volume || 0,
      cpc: kd.keyword_info?.cpc || 0,
      competition: kd.keyword_info?.competition || 0,
      search_intent: (kd.search_intent_info?.main_intent || 'informational').toLowerCase(),
      source: 'related'
    });
    // Auch Related Keywords aus dem Cluster hinzufügen
    const related = item.related_keywords || [];
    for (const rel of related) {
      allKeywords.push({
        keyword: (rel.keyword || '').toLowerCase().trim(),
        search_volume: rel.keyword_info?.search_volume || 0,
        cpc: rel.keyword_info?.cpc || 0,
        competition: rel.keyword_info?.competition || 0,
        search_intent: (rel.search_intent_info?.main_intent || 'informational').toLowerCase(),
        source: 'related_cluster'
      });
    }
  }
}

// Leere Keywords entfernen
const filtered = allKeywords.filter(kw => kw.keyword && kw.keyword.length > 0);

return [{ json: { all_keywords: filtered, total_raw: filtered.length } }];

// Keywords gruppieren und bereinigen
// Ähnliche Keywords (gleiche Wörter, andere Reihenfolge) werden gruppiert
// Pro Gruppe → das Keyword mit höchstem Suchvolumen wird Hauptkeyword

const allKeywords = $input.all()[0].json.all_keywords;

// Hilfsfunktion: Wörter sortieren für Vergleich
function normalizeForGrouping(keyword) {
  return keyword
    .toLowerCase()
    .replace(/[^a-zäöüß0-9\s]/g, '')
    .split(/\s+/)
    .filter(w => w.length > 0)
    .sort()
    .join(' ');
}

// Duplikate entfernen (exakt gleiche Keywords → höchstes SV behalten)
const deduped = new Map();
for (const kw of allKeywords) {
  const existing = deduped.get(kw.keyword);
  if (!existing || kw.search_volume > existing.search_volume) {
    deduped.set(kw.keyword, kw);
  }
}

// Komplette Keywordliste (Worksheet 2)
const completeList = Array.from(deduped.values())
  .sort((a, b) => b.search_volume - a.search_volume);

// Keywords nach normalisierten Wörtern gruppieren
const groups = new Map();
for (const kw of completeList) {
  const normalized = normalizeForGrouping(kw.keyword);
  if (!groups.has(normalized)) {
    groups.set(normalized, []);
  }
  groups.get(normalized).push(kw);
}

// Pro Gruppe: Hauptkeyword = höchstes Suchvolumen
const cleanedList = [];
const groupMapping = [];

let groupId = 1;
for (const [normalizedKey, keywords] of groups) {
  // Sortiere nach SV absteigend
  keywords.sort((a, b) => b.search_volume - a.search_volume);
  const primary = keywords[0];

  cleanedList.push({
    keyword: primary.keyword,
    search_volume: primary.search_volume,
    search_intent: primary.search_intent,
    cpc: primary.cpc,
    competition: primary.competition,
    status: 'offen',
    group_id: groupId,
    variations_count: keywords.length
  });

  // Alle Keywords der Gruppe für Worksheet 3
  for (const kw of keywords) {
    groupMapping.push({
      group_id: groupId,
      primary_keyword: primary.keyword,
      keyword: kw.keyword,
      search_volume: kw.search_volume,
      search_intent: kw.search_intent,
      is_primary: kw.keyword === primary.keyword
    });
  }
  groupId++;
}

// Nach Suchvolumen sortieren
cleanedList.sort((a, b) => b.search_volume - a.search_volume);

return [{
  json: {
    cleaned_keywords: cleanedList,
    complete_keywords: completeList,
    keyword_groups: groupMapping,
    stats: {
      total_raw: allKeywords.length,
      total_unique: completeList.length,
      total_groups: cleanedList.length
    }
  }
}];

// Sheet ID extrahieren und Worksheet-Namen vorbereiten
const sheetResponse = $input.all()[0].json;
const spreadsheetId = sheetResponse.id;
const spreadsheetUrl = `https://docs.google.com/spreadsheets/d/${spreadsheetId}`;

return [{
  json: {
    spreadsheet_id: spreadsheetId,
    spreadsheet_url: spreadsheetUrl
  }
}];

// Daten für alle 3 Worksheets als Sheets API values vorbereiten
const data = $('Deduplicate & Group Keywords').item.json;
const spreadsheetId = $('Extract Sheet ID').item.json.spreadsheet_id;

// Worksheet 1: Bereinigte Keywordliste (1 Keyword pro Gruppe)
const sheet1Header = ['Keyword', 'Suchvolumen', 'Search Intent', 'CPC', 'Competition', 'Status', 'Keyword-Gruppe', 'Variationen'];
const sheet1Rows = data.cleaned_keywords.map(kw => [
  kw.keyword,
  kw.search_volume,
  kw.search_intent,
  kw.cpc,
  kw.competition,
  kw.status,
  kw.group_id,
  kw.variations_count
]);

// Worksheet 2: Komplette Keywordliste (alle Keywords inkl. Variationen)
const sheet2Header = ['Keyword', 'Suchvolumen', 'Search Intent', 'CPC', 'Competition'];
const sheet2Rows = data.complete_keywords.map(kw => [
  kw.keyword,
  kw.search_volume,
  kw.search_intent,
  kw.cpc,
  kw.competition
]);

// Worksheet 3: Keyword-Gruppen (zeigt Zuordnung: welche Keywords gehören zusammen)
const sheet3Header = ['Gruppen-ID', 'Hauptkeyword', 'Keyword-Variation', 'Suchvolumen', 'Search Intent', 'Ist Hauptkeyword'];
const sheet3Rows = data.keyword_groups.map(g => [
  g.group_id,
  g.primary_keyword,
  g.keyword,
  g.search_volume,
  g.search_intent,
  g.is_primary ? 'Ja' : 'Nein'
]);

return [{
  json: {
    spreadsheet_id: spreadsheetId,
    batch_data: {
      valueInputOption: 'RAW',
      data: [
        {
          range: 'Bereinigte Keywordliste!A1',
          values: [sheet1Header, ...sheet1Rows]
        },
        {
          range: 'Komplette Keywordliste!A1',
          values: [sheet2Header, ...sheet2Rows]
        },
        {
          range: 'Keyword-Gruppen!A1',
          values: [sheet3Header, ...sheet3Rows]
        }
      ]
    },
    stats: data.stats
  }
}];

// Bereinigte Keywords als einzelne Items für den Loop vorbereiten
const data = $('Deduplicate & Group Keywords').item.json;
const cleanedKeywords = data.cleaned_keywords;
const extractData = $('Extract Task Data').item.json;
const themenCluster = extractData.themen_cluster;
const themenClusterValue = extractData.themen_cluster_value;
const kunde = extractData.kunde;

// Pro Keyword ein Item erstellen
return cleanedKeywords.map(kw => ({
  json: {
    keyword: kw.keyword,
    search_volume: kw.search_volume,
    search_intent: kw.search_intent,
    themen_cluster: themenCluster,
    themen_cluster_value: themenClusterValue,
    kunde: kunde,
    status: 'keyword'
  }
}));

